INSERT INTO organs (id,system_id,name_ar,name_en,latin_name,summary_ar,summary_en,status_code) VALUES ('organ-femur','sys-skeletal','عظم الفخذ','Femur','','عظم طويل يمتد بين الورك والركبة. يوضح تنظيم جسم العظم ونهايتيه.','A long bone between hip and knee, illustrating the shaft and ends of a long bone.','EDUCATIONAL_FOUNDATION_PUBLISHED') ON CONFLICT DO NOTHING;
INSERT INTO citations (entity_type,entity_id,source_id,citation_note) VALUES ('ORGAN','organ-femur','src-openstax-2026-bone','Brief attributed educational adaptation. Independent scientific review deferred; no clinical recommendations.') ON CONFLICT DO NOTHING;
