INSERT INTO organ_sections (id,organ_id,section_key,title_ar,title_en,body_ar,body_en,order_index) VALUES ('sec-femur-foundation','organ-femur','ANATOMY_FUNCTION','البنية والوظيفة','Structure and function','يحيط العظم الكثيف بالتجويف النخاعي في الجسم، بينما تحتوي النهايتان على عظم إسفنجي. يغطي الغضروف المفصلي السطوح المشاركة في المفاصل.','Compact bone surrounds the shaft cavity; spongy bone occupies the ends. Articular cartilage covers joint surfaces.',1) ON CONFLICT DO NOTHING;
INSERT INTO organs (id,system_id,name_ar,name_en,latin_name,summary_ar,summary_en,status_code) VALUES ('organ-biceps-brachii','sys-muscular','العضلة ذات الرأسين العضدية','Biceps brachii','','عضلة في مقدمة العضد تسهم في ثني المرفق واستلقاء الساعد.','An anterior arm muscle contributing to elbow flexion and forearm supination.','EDUCATIONAL_FOUNDATION_PUBLISHED') ON CONFLICT DO NOTHING;
INSERT INTO citations (entity_type,entity_id,source_id,citation_note) VALUES ('ORGAN','organ-biceps-brachii','src-openstax-2026-muscle','Brief attributed educational adaptation. Independent scientific review deferred; no clinical recommendations.') ON CONFLICT DO NOTHING;
