INSERT INTO organ_sections (id,organ_id,section_key,title_ar,title_en,body_ar,body_en,order_index) VALUES ('sec-biceps-brachii-foundation','organ-biceps-brachii','ANATOMY_FUNCTION','البنية والوظيفة','Structure and function','للعضلة رأسان وتعبر مفصلي الكتف والمرفق. تسهم أيضًا في ثني الذراع عند الكتف؛ وتساعد العضلة العضدية العميقة لها في ثني المرفق.','It has two heads and crosses shoulder and elbow. It also assists shoulder flexion; the deeper brachialis contributes to elbow flexion.',1) ON CONFLICT DO NOTHING;
INSERT INTO organs (id,system_id,name_ar,name_en,latin_name,summary_ar,summary_en,status_code) VALUES ('organ-spleen','sys-immune-lymphatic','الطحال','Spleen','','عضو لمفي ثانوي يرتبط بالمعدة ويسهم في تنقية الدم والاستجابة المناعية.','A secondary lymphoid organ associated with the stomach, contributing to blood filtration and immune responses.','EDUCATIONAL_FOUNDATION_PUBLISHED') ON CONFLICT DO NOTHING;
INSERT INTO citations (entity_type,entity_id,source_id,citation_note) VALUES ('ORGAN','organ-spleen','src-openstax-2026-lymph','Brief attributed educational adaptation. Independent scientific review deferred; no clinical recommendations.') ON CONFLICT DO NOTHING;
