INSERT INTO organ_sections (id,organ_id,section_key,title_ar,title_en,body_ar,body_en,order_index) VALUES ('sec-spleen-foundation','organ-spleen','ANATOMY_FUNCTION','البنية والوظيفة','Structure and function','يحتوي على لب أحمر ولب أبيض. تسهم خلاياه البلعمية في إزالة كريات الدم الحمراء المتقادمة ومواد أخرى من الدم؛ ويشارك في الاستجابة لمستضدات تصل عبر الدم.','It contains red and white pulp. Phagocytic cells remove ageing red cells and other material; immune cells respond to blood-borne antigens.',1) ON CONFLICT DO NOTHING;
INSERT INTO organs (id,system_id,name_ar,name_en,latin_name,summary_ar,summary_en,status_code) VALUES ('organ-skin','sys-integumentary','الجلد','Skin','','غلاف الجسم الواقي، ويتكون من البشرة والأدمة.','The protective body covering, comprising epidermis and dermis.','EDUCATIONAL_FOUNDATION_PUBLISHED') ON CONFLICT DO NOTHING;
INSERT INTO citations (entity_type,entity_id,source_id,citation_note) VALUES ('ORGAN','organ-skin','src-openstax-2026-skin','Brief attributed educational adaptation. Independent scientific review deferred; no clinical recommendations.') ON CONFLICT DO NOTHING;
