INSERT INTO organ_sections (id,organ_id,section_key,title_ar,title_en,body_ar,body_en,order_index) VALUES ('sec-skin-foundation','organ-skin','ANATOMY_FUNCTION','البنية والوظيفة','Structure and function','البشرة ظهارة متقرنة لا تحتوي أوعية دموية. تضم الأدمة أوعية وأعصابًا وبنى ملحقة. يقع النسيج تحت الجلد أسفل الأدمة ويحتوي نسيجًا ضامًا ودهنيًا.','The keratinized epidermis lacks blood vessels. The dermis contains vessels, nerves and accessory structures. Subcutaneous connective and fatty tissue lies beneath the dermis.',1) ON CONFLICT DO NOTHING;
INSERT INTO organs (id,system_id,name_ar,name_en,latin_name,summary_ar,summary_en,status_code) VALUES ('organ-ovaries','sys-reproductive','المبيضان','Ovaries','','غدتان تناسليتان في الحوض تحتويان الخلايا البيضية وتنتجان هرمونات تناسلية.','Paired pelvic gonads containing oocytes and producing reproductive hormones.','EDUCATIONAL_FOUNDATION_PUBLISHED') ON CONFLICT DO NOTHING;
INSERT INTO citations (entity_type,entity_id,source_id,citation_note) VALUES ('ORGAN','organ-ovaries','src-openstax-2026-ovary','Brief attributed educational adaptation. Independent scientific review deferred; no clinical recommendations.') ON CONFLICT DO NOTHING;
INSERT INTO source_attributions (id,entity_id,entity_type,source_id,imported_at,human_reviewed_at,review_status) VALUES ('foundation-2026-organ-ovaries','organ-ovaries','ORGAN','src-openstax-2026-ovary','2026-10-25',NULL,'under_review') ON CONFLICT DO NOTHING;
INSERT INTO organ_sections (id,organ_id,section_key,title_ar,title_en,body_ar,body_en,order_index) VALUES ('sec-ovaries-foundation','organ-ovaries','ANATOMY_FUNCTION','البنية والوظيفة','Structure and function','تحتوي القشرة على جريبات، يتألف كل منها من خلية بيضية وخلايا داعمة. يضم اللب الداخلي أوعية دموية ولمفية وأعصابًا.','The cortex contains follicles formed by an oocyte and supporting cells. The inner medulla contains blood and lymph vessels and nerves.',1) ON CONFLICT DO NOTHING;
INSERT INTO organs (id,system_id,name_ar,name_en,latin_name,summary_ar,summary_en,status_code) VALUES ('organ-testes','sys-reproductive','الخصيتان','Testes','','غدتان تناسليتان داخل الصفن تنتجان الحيوانات المنوية والأندروجينات.','Paired gonads within the scrotum producing sperm and androgens.','EDUCATIONAL_FOUNDATION_PUBLISHED') ON CONFLICT DO NOTHING;
INSERT INTO citations (entity_type,entity_id,source_id,citation_note) VALUES ('ORGAN','organ-testes','src-openstax-2026-testis','Brief attributed educational adaptation. Independent scientific review deferred; no clinical recommendations.') ON CONFLICT DO NOTHING;
INSERT INTO source_attributions (id,entity_id,entity_type,source_id,imported_at,human_reviewed_at,review_status) VALUES ('foundation-2026-organ-testes','organ-testes','ORGAN','src-openstax-2026-testis','2026-10-25',NULL,'under_review') ON CONFLICT DO NOTHING;
INSERT INTO organ_sections (id,organ_id,section_key,title_ar,title_en,body_ar,body_en,order_index) VALUES ('sec-testes-foundation','organ-testes','ANATOMY_FUNCTION','البنية والوظيفة','Structure and function','تقسم حواجز من نسيج ضام الخصية إلى فصيصات تضم الأنابيب المنوية. تتكون الحيوانات المنوية في هذه الأنابيب ثم تنتقل إلى البربخ لاستكمال نضجها.','Connective tissue septa divide each testis into lobules containing seminiferous tubules. Sperm form there and move to the epididymis for further maturation.',1) ON CONFLICT DO NOTHING;
INSERT INTO organs (id,system_id,name_ar,name_en,latin_name,summary_ar,summary_en,status_code) VALUES ('organ-eye','sys-special-senses','العين','Eye','','عضو الإبصار؛ تحتوي شبكيته على مستقبلات ضوئية.','The organ of vision; its retina contains photoreceptors.','EDUCATIONAL_FOUNDATION_PUBLISHED') ON CONFLICT DO NOTHING;
INSERT INTO citations (entity_type,entity_id,source_id,citation_note) VALUES ('ORGAN','organ-eye','src-openstax-2026-senses','Brief attributed educational adaptation. Independent scientific review deferred; no clinical recommendations.') ON CONFLICT DO NOTHING;
INSERT INTO source_attributions (id,entity_id,entity_type,source_id,imported_at,human_reviewed_at,review_status) VALUES ('foundation-2026-organ-eye','organ-eye','ORGAN','src-openstax-2026-senses','2026-10-25',NULL,'under_review') ON CONFLICT DO NOTHING;
INSERT INTO organ_sections (id,organ_id,section_key,title_ar,title_en,body_ar,body_en,order_index) VALUES ('sec-eye-foundation','organ-eye','ANATOMY_FUNCTION','البنية والوظيفة','Structure and function','تستجيب العصي والمخاريط للضوء. تعالج دوائر الشبكية الإشارة، وتكوّن محاور خلاياها العقدية العصب البصري.','Rods and cones respond to light. Retinal circuits process signals; ganglion-cell axons form the optic nerve.',1) ON CONFLICT DO NOTHING;
INSERT INTO organs (id,system_id,name_ar,name_en,latin_name,summary_ar,summary_en,status_code) VALUES ('organ-inner-ear','sys-special-senses','الأذن الداخلية','Inner ear','','تضم تراكيب للسمع والتوازن.','Contains structures for hearing and balance.','EDUCATIONAL_FOUNDATION_PUBLISHED') ON CONFLICT DO NOTHING;
INSERT INTO citations (entity_type,entity_id,source_id,citation_note) VALUES ('ORGAN','organ-inner-ear','src-openstax-2026-senses','Brief attributed educational adaptation. Independent scientific review deferred; no clinical recommendations.') ON CONFLICT DO NOTHING;
INSERT INTO source_attributions (id,entity_id,entity_type,source_id,imported_at,human_reviewed_at,review_status) VALUES ('foundation-2026-organ-inner-ear','organ-inner-ear','ORGAN','src-openstax-2026-senses','2026-10-25',NULL,'under_review') ON CONFLICT DO NOTHING;
INSERT INTO organ_sections (id,organ_id,section_key,title_ar,title_en,body_ar,body_en,order_index) VALUES ('sec-inner-ear-foundation','organ-inner-ear','ANATOMY_FUNCTION','البنية والوظيفة','Structure and function','تسهم الخلايا الشعرية في القوقعة في تحويل الاهتزاز إلى إشارة عصبية. تسهم بنى الدهليز والقنوات نصف الدائرية في استشعار وضع الرأس وحركته.','Cochlear hair cells transduce vibration. Vestibular structures and semicircular canals help sense head position and movement.',1) ON CONFLICT DO NOTHING;
